import React from 'react';
import { Link } from 'react-router-dom';
import './menu-principal.css';
import { Home, User, List } from 'lucide-react';
import { useState } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faHouse, faMedal, faUser, faEllipsisH, faDumbbell, faBrain, faHeartPulse, faKidney, faLungs, faStomach, faPrescriptionBottle, faHand, faSwimmer, faSkullCrossbones, faTrophy, faVolumeUp, faVolumeMute, faStar, faHeart } from '@fortawesome/free-solid-svg-icons';

const MenuPrincipal = () => {
    const [selectedMenu, setSelectedMenu] = useState('Inicio');
    const [soundEnabled, setSoundEnabled] = useState(true);
    const [page, setPage] = useState(1);

    const handleMenuClick = (menu) => {
        setSelectedMenu(menu);
    };

    const toggleSound = () => {
        setSoundEnabled(!soundEnabled);
    };

    const courses = [
        { name: 'Membrana Celular', icon: faWallCell, color: 'cyano' },
        { name: 'Fisiologia Muscular', icon: faDumbbell, color: 'orange' },
        { name: 'Sistema Nervoso', icon: faBrain, color: 'green' },
        { name: 'Sistema Circulatório', icon: faHeartPulse, color: 'red' },
        { name: 'Sistema Urinário', icon: faKidney, color: 'lightblue' },
        { name: 'Sistema Respiratório', icon: faLungs, color: 'green' },
        { name: 'Sistema Digestório', icon: faStomach, color: 'yellow' },
        { name: 'Sistema Endócrino', icon: faPrescriptionBottle, color: 'purple' },
        { name: 'Sistema Reprodutor', icon: faHand, color: 'gray' },
        { name: 'Fisiologia do Esporte', icon: faSwimmer, color: 'darkblue' },
        { name: 'Duelo', icon: faSkullCrossbones, color: 'darkblue' },
        { name: 'Liga das Estrelas', icon: faTrophy, color: 'pink' },
    ];

    const coursesPerPage = 6;
    const startIndex = (page - 1) * coursesPerPage;
    const endIndex = Math.min(startIndex + coursesPerPage, courses.length);
    const displayedCourses = courses.slice(startIndex, endIndex);

    return (
        <div className="main-container">
            <div className="sidebar-left">
                <div className="logo">Fisiogame</div>
                <ul className="menu">
                    <li className={selectedMenu === 'Inicio' ? 'active' : ''} onClick={() => handleMenuClick('Inicio')}>
                        <FontAwesomeIcon icon={faHouse} /> Inicio
                    </li>
                    <li className={selectedMenu === 'Ranking' ? 'active' : ''} onClick={() => handleMenuClick('Ranking')}>
                        <FontAwesomeIcon icon={faMedal} /> Ranking
                    </li>
                    <li className={selectedMenu === 'Perfil' ? 'active' : ''} onClick={() => handleMenuClick('Perfil')}>
                        <FontAwesomeIcon icon={faUser} /> Perfil
                    </li>
                    <li className={selectedMenu === 'Mais' ? 'active' : ''} onClick={() => handleMenuClick('Mais')}>
                        <FontAwesomeIcon icon={faEllipsisH} /> Mais
                    </li>
                </ul>
            </div>
            <div className="content">
                <div className="header">
                    <div className="header-text">Selecione um assunto para continuar</div>
                </div>
                <div className="courses-container">
                    {displayedCourses.map((course) => (
                        <div key={course.name} className={`course-button ${course.color}`}>
                            <FontAwesomeIcon icon={course.icon} /> {course.name}
                        </div>
                    ))}
                    {courses.length > endIndex && (
                        <button className="next-button" onClick={() => setPage(page + 1)}>Próximo</button>
                    )}
                    {courses.length > coursesPerPage && (
                        <div className="pagination">
                            {Array.from({ length: Math.ceil(courses.length / coursesPerPage) }, (_, i) => (
                                <button key={i + 1} onClick={() => setPage(i + 1)} className={page === i + 1 ? 'active' : ''}>
                                    {i + 1}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </div>
            <div className="sidebar-right">
                <div className="sound" onClick={toggleSound}>
                    {soundEnabled ? (
                        <>
                            <FontAwesomeIcon icon={faVolumeUp} /> Desativar Som
                        </>
                    ) : (
                        <>
                            <FontAwesomeIcon icon={faVolumeMute} /> Ativar Som
                        </>
                    )}
                </div>
                <div className="score">
                    <FontAwesomeIcon icon={faStar} /> 350 Quirons
                </div>
                <div className="lives">
                    <FontAwesomeIcon icon={faHeart} /> 5 Vidas
                </div>
            </div>
        </div>
    );
};

export default MenuPrincipal;
